insert into ufologia.criptopaleontologia
  (titulo, slug, categoria, periodo, descricao, teoria_conspiracao, ordem, publicado)
values

('A civilização remanescente', 'civilizacao-remanescente', 'Conspiração', 'Cataclisma proposto há ~12.900 anos',
 'A Hipótese do Impacto do Younger Dryas propõe que uma explosão ou impacto cósmico, há cerca de 12.900 anos, teria desestabilizado parte da camada de gelo Laurentide e provocado o resfriamento abrupto conhecido como Younger Dryas, contribuindo pra extinção da megafauna do fim do Pleistoceno. É uma hipótese científica real e genuinamente controversa: desde que foi proposta em 2007, recebeu tanto revisões que a consideram prematuramente rejeitada (2021) quanto refutações abrangentes que a descartam por completo (2023). O debate segue em aberto na comunidade científica, sem consenso.',
 'A partir dessa hipótese ainda não resolvida, teóricos de fronteira dão um salto adicional: propõem que esse cataclisma destruiu uma civilização avançada pré-glacial, e que um pequeno grupo sobreviveu escondido — sob os oceanos ou em regiões isoladas — mantendo e avançando sua tecnologia em segredo por milênios. Segundo essa leitura, ocupantes de OVNI com aparência humana, símbolos antigos relatados em encontros modernos, e a sensação de que "o fenômeno" acompanha a humanidade há muito tempo, seriam sinais dessa civilização remanescente — não visitantes de outro planeta, mas sobreviventes da própria Terra. Alguns defensores ligam a teoria a episódios como a Operação Highjump, Roswell e o suposto encontro de Eisenhower com seres de aparência humana nos anos 1950, propondo que esses seriam os momentos em que governos modernos teriam descoberto ou estabelecido contato com esse grupo.',
 33, true),

('A rede de bases subterrâneas', 'rede-bases-subterraneas', 'Conspiração', 'Achado contábil de 2017; alegações desde então',
 'Em 2017, a ex-secretária assistente do Departamento de Habitação dos EUA (HUD) Catherine Austin Fitts e o economista Mark Skidmore publicaram uma análise de relatórios oficiais do Inspetor-Geral, encontrando cerca de US$ 21 trilhões em "ajustes contábeis não documentados" no Pentágono e no HUD entre 1998 e 2015 — uma discrepância real, noticiada até pela revista americana The Nation. Os próprios autores do estudo, porém, não afirmam que todo esse valor tenha sido de fato desviado ou usado secretamente; parte dele pode representar apenas falhas crônicas de contabilidade em sistemas legados.',
 'A partir desse achado contábil real, Fitts e outros pesquisadores de teorias de fronteira especulam que o dinheiro financiaria uma rede de bases subterrâneas e submarinas conectadas por sistemas de transporte avançados — estimativas informais, sem qualquer verificação independente, chegam a 170 instalações só nos EUA. A teoria propõe que essas bases serviriam pra abrigar uma elite durante um "evento de extinção" futuro, ou que teriam relação com a suposta civilização remanescente citada acima. Não existe evidência pública de que os ajustes contábeis tenham sido de fato direcionados a esse fim — a ligação entre o dinheiro desaparecido e bases secretas é inteiramente especulativa por parte de quem a defende.',
 34, true);
